module sv_x_csa_mac_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic [7:0] op_a,
    input  logic [7:0] op_b,
    input  logic [7:0] op_c,
    output logic [7:0] sum_out,
    output logic [7:0] carry_out
);
    logic [7:0] sum_comb, carry_comb;

    assign sum_comb = op_a ^ op_b ^ op_c;
    assign carry_comb = (op_a & op_b) | (op_b & op_c) | (op_a & op_c);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_out <= 8'd0;
            carry_out <= 8'd0;
        end else begin
            sum_out <= sum_comb;
            // BUG: shifts by 2 bits instead of 1!
            carry_out <= {carry_comb[5:0], 2'b00}; // BUG!
        end
    end
endmodule

