module sv_x_fixed_sqrt_fix(
    input  logic [7:0] val_in,
    output logic [3:0] root_out
);
    logic [3:0] r;
    logic [7:0] rem;

    always_comb begin
        if (val_in >= 8'd225) r = 4'd15;
        else if (val_in >= 8'd196) r = 4'd14;
        else if (val_in >= 8'd169) r = 4'd13;
        else if (val_in >= 8'd144) r = 4'd12;
        else if (val_in >= 8'd121) r = 4'd11;
        else if (val_in >= 8'd100) r = 4'd10;
        else if (val_in >= 8'd81)  r = 4'd9;
        else if (val_in >= 8'd64)  r = 4'd8;
        else if (val_in >= 8'd49)  r = 4'd7;
        else if (val_in >= 8'd36)  r = 4'd6;
        else if (val_in >= 8'd25)  r = 4'd5;
        else if (val_in >= 8'd16)  r = 4'd4;
        else if (val_in >= 8'd9)   r = 4'd3;
        else if (val_in >= 8'd4)   r = 4'd2;
        else if (val_in >= 8'd1)   r = 4'd1;
        else                       r = 4'd0;

        rem = val_in - (r * r);

        // BUG: Inverted condition rounds up when rem < r!
        if (rem < {4'd0, r}) begin // BUG!
            root_out = r + 4'd1;
        end else begin
            root_out = r;
        end
    end
endmodule

