module sv_x_rle_decompress_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       token_valid,
    input  logic [3:0] sym_in,
    input  logic [3:0] len_in,
    output logic       token_ready,
    output logic       data_valid,
    output logic [3:0] data_out
);
    logic [3:0] cur_sym;
    logic [3:0] rem_len;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_sym <= 4'd0;
            rem_len <= 4'd0;
            data_valid <= 1'b0;
            data_out <= 4'd0;
            token_ready <= 1'b1;
        end else begin
            if (rem_len > 4'd1) begin
                rem_len <= rem_len - 4'd1;
                data_valid <= 1'b1;
                data_out <= cur_sym;
                token_ready <= (rem_len == 4'd2);
            end else if (token_valid && token_ready) begin
                cur_sym <= sym_in;
                // BUG: Subtracts 1 prematurely, losing a symbol!
                rem_len <= len_in - 4'd1; // BUG!
                data_valid <= 1'b1;
                data_out <= sym_in;
                token_ready <= (len_in == 4'd1);
            end else begin
                rem_len <= 4'd0;
                data_valid <= 1'b0;
                data_out <= 4'd0;
                token_ready <= 1'b1;
            end
        end
    end
endmodule

