module sv_x_watchdog_race_fix(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       pet,
    output logic [3:0] count,
    output logic       early_err,
    output logic       timeout_err
);
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 4'd0;
            early_err <= 1'b0;
            timeout_err <= 1'b0;
        end else begin
            if (pet) begin
                // BUG: Uses <= 4 instead of < 4, treating boundary count 4 as an error!
                if (count <= 4'd4) begin // BUG!
                    early_err <= 1'b1;
                    count <= 4'd0;
                end else begin
                    early_err <= 1'b0;
                    count <= 4'd0;
                end
            end else if (count >= 4'd8) begin
                timeout_err <= 1'b1;
                count <= 4'd8;
            end else begin
                count <= count + 4'd1;
                early_err <= 1'b0;
                timeout_err <= 1'b0;
            end
        end
    end
endmodule

module sv_x_fix_regfile_bypass(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       we,
    input  logic [1:0] waddr,
    input  logic [7:0] wdata,
    input  logic [1:0] raddr,
    output logic [7:0] rdata_out
);
    logic [7:0] rf [3:0];
    integer i;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 4; i = i + 1)
                rf[i] <= 8'd0;
        end else if (we) begin
            rf[waddr] <= wdata;
        end
    end

    // BUG: missing write-forwarding bypass logic
    assign rdata_out = rf[raddr];

endmodule

