module sv_x_fix_pipe_valid_stall(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       stall,
    input  logic       in_val,
    input  logic [7:0] in_data,
    output logic       stage_val,
    output logic [7:0] stage_data
);
    // BUG: clears stage_val on stall instead of holding state
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stage_val  <= 1'b0;
            stage_data <= 8'd0;
        end else if (stall) begin
            stage_val  <= 1'b0;
        end else begin
            stage_val  <= in_val;
            stage_data <= in_data;
        end
    end

endmodule

module sv_x_fix_glitch_filter(
    input  logic clk,
    input  logic rst_n,
    input  logic raw_btn,
    output logic btn_clean,
    output logic [2:0] sample_hist
);
    logic [2:0] hist;

    // BUG: hist not cleared on reset
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            btn_clean <= 1'b0;
        end else begin
            hist <= {hist[1:0], raw_btn};
            btn_clean <= (hist[0] & hist[1]) | (hist[1] & hist[2]) | (hist[0] & hist[2]);
        end
    end

    assign sample_hist = hist;

endmodule

