module sv_x_fix_circ_buf_wrap(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       pop,
    input  logic       not_empty,
    output logic [3:0] tail_ptr,
    output logic       wrap_pulse
);
    // BUG: premature wrap at 14 instead of 15
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tail_ptr   <= 4'd0;
            wrap_pulse <= 1'b0;
        end else if (pop && not_empty) begin
            if (tail_ptr == 4'd14) begin
                tail_ptr   <= 4'd0;
                wrap_pulse <= 1'b1;
            end else begin
                tail_ptr   <= tail_ptr + 1'b1;
                wrap_pulse <= 1'b0;
            end
        end else begin
            wrap_pulse <= 1'b0;
        end
    end

endmodule

